def zigzag_level_order(root):
    from collections import deque
    if root is None:
        return []
    queue, answer = deque([root]), []
    while queue:
        row = []
        for _ in range(len(queue)):
            node = queue.popleft()
            row.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        answer.append(row[::-1] if len(answer) % 2 else row)
    return answer

